import itertools
import random
random.seed(42)
def can_schedule():
    all_pairs = set(itertools.combinations(range(18),2))
    schedule = []
    for week in range(7):
        remaining_pairs = all_pairs.copy()
        groups = []
        for g in range(6):
            possible_triples = [comb for comb in itertools.combinations(range(18),3) if all(p in remaining_pairs for p in itertools.combinations(comb,2))]
            if not possible_triples:
                return None
            triple = random.choice(possible_triples)
            groups.append(triple)
            for p in itertools.combinations(triple,2):
                if p in remaining_pairs:
                    remaining_pairs.remove(p)
        schedule.append(groups)
        for group in groups:
            for p in itertools.combinations(group,2):
                if p in all_pairs:
                    all_pairs.remove(p)
    return schedule
